-- ============================================
-- LUMA — Thème 14 : 3e scénario COURT x4 — Demander son chemin sur une aire d'autoroute
-- ============================================


update scenarios set content = '{"characters": {"attendant": "l''employé de la station"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You realize you missed your exit twenty minutes ago. Time to ask for directions.)", "text_fr": "(Vous réalisez que vous avez raté votre sortie il y a vingt minutes. Il est temps de demander votre chemin.)", "choices": [{"text": "Excuse me, I think I missed my exit for Route 9. Can you help?", "text_fr": "Excusez-moi, je pense avoir raté ma sortie pour la Route 9. Vous pouvez m''aider ?", "next": "n2"}, {"text": "Hi, is there a way back to the highway heading north from here?", "text_fr": "Bonjour, il y a un moyen de retourner sur l''autoroute vers le nord d''ici ?", "next": "n2b"}]}, "n2": {"speaker": "attendant", "text": "Oh yeah, that exit''s about fifteen miles back. Easiest is to take the next exit and loop around.", "text_fr": "Oh ouais, cette sortie est à environ quinze miles en arrière. Le plus simple c''est de prendre la prochaine sortie et de faire une boucle.", "choices": [{"text": "Got it, thank you! How far is the next exit from here?", "text_fr": "Compris, merci ! La prochaine sortie est à quelle distance d''ici ?", "next": "n3"}]}, "n2b": {"speaker": "attendant", "text": "Sure thing, take this on-ramp right here, it''ll get you going north again.", "text_fr": "Bien sûr, prenez cette bretelle d''accès juste ici, ça vous remettra en direction du nord.", "choices": [{"text": "Perfect, thank you for the quick help!", "text_fr": "Parfait, merci pour l''aide rapide !", "next": "n3b"}]}, "n3": {"speaker": "attendant", "text": "About five miles up the road, you can''t miss it.", "text_fr": "Environ cinq miles plus loin sur la route, vous pouvez pas la manquer.", "choices": [{"text": "Great, I appreciate your help getting back on track.", "text_fr": "Super, j''apprécie votre aide pour me remettre sur la bonne voie.", "next": "n4"}]}, "n3b": {"speaker": "attendant", "text": "No problem at all, happens to travelers all the time around here.", "text_fr": "Aucun problème, ça arrive tout le temps aux voyageurs par ici.", "choices": [{"text": "That''s reassuring to hear, thank you again.", "text_fr": "Ça rassure d''entendre ça, merci encore.", "next": "n4"}]}, "n4": {"speaker": "attendant", "text": "No worries, safe travels wherever you''re headed!", "text_fr": "Pas de souci, bonne route où que vous alliez !", "choices": [{"text": "Thank you, I''ll get back on the road now.", "text_fr": "Merci, je reprends la route maintenant.", "next": "end_directed"}]}, "end_directed": {"speaker": "you_thought", "text": "(Relieved, you head back to your car, ready to get back on track.)", "text_fr": "(Soulagé, vous retournez à votre voiture, prêt à vous remettre en route.)", "end": true, "ending_label": "Chemin retrouvé grâce à un local sympa 🛣️✅"}}}'::jsonb, is_playable = true
where title = 'Demander son chemin sur une aire d''''autoroute'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
